// #3be8ad (№33) «Android - ברשימת הברכות שם הברכה ו-placeholder של החיפוש נחתכים בזום 200%» — עבר QA 09.11.
//   מה רצוי: «בזום 200% שם הברכה ברשימה מוצג במלואו (נשבר לשורות בין מילים…), וה-placeholder של החיפוש נקרא במלואו».
//   Было: «נטילת ידי…», «חיפוש בר», в תהילים «חיפוש לפי מספר פ…».
// Факт 09.11 (Pixel 6, wm density 840): «נטילת ידים והמוציא» целиком; «חיפוש ברכה» и «חיפוש לפי מספר פרק או מילים» целиком (efdc1ec).
// Кейс: .qa/tests/zoom-200/Z2-07-brachot-search.md. Только просмотр.
import { driver, expect } from '@wdio/globals';
import { goTab } from '../../helpers/nav.ts';
import { goHome, nodes, type UiNode } from '../_lib/readiness-1910.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { openBrachotList } from '../_lib/app-2110.ts';
import { zoomOn, zoomOff, textNode, insideScreenX, linesAtZoom, wordCount, notTruncated, saveShot } from '../_lib/app-0911.ts';

const BRACHA = 'נטילת ידים והמוציא';
const PH_BRACHOT = 'חיפוש ברכה';
const PH_TEHILIM = 'חיפוש לפי מספר פרק או מילים';

/** Пустое поле поиска показывает placeholder как text у EditText. */
async function placeholder(text: string): Promise<UiNode> {
  return textNode(text, () => true).catch(async () => {
    const n = (await nodes()).find((x) => /EditText/.test(x.type) && x.label === text);
    if (!n) throw new Error(`нет поля поиска с placeholder «${text}»`);
    return n;
  });
}
async function openTehilimList() {
  await goHome(); await goTab('ברכות');
  if (!(await nodes()).some((n) => n.label === 'פרקי אבות')) await goTab('תהילים');
}
const anyNode = async (text: string) => {
  const n = (await nodes()).find((x) => x.label === text && x.visible && x.w > 0);
  if (!n) throw new Error(`нет «${text}»`);
  return n;
};

describe('09.11 — зум 200% (Android): ברכות — имя в списке и подсказки поиска (#3be8ad)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Z2-07 При wm density 840 «נטילת ידים והמוציא» целиком (переносы между словами), placeholder «חיפוש ברכה» и «חיפוש לפי מספר פרק או מילים» целиком #3be8ad @android @prod-safe @manual-check', async () => {
    await openBrachotList(BRACHA);
    const nB = await textNode(BRACHA);
    const nPhB = await anyNode(PH_BRACHOT).catch(() => placeholder(PH_BRACHOT));
    await openTehilimList();
    const nPhT = await anyNode(PH_TEHILIM).catch(() => placeholder(PH_TEHILIM));

    await goHome();
    await zoomOn();

    // 1. Список брахот.
    await openBrachotList(BRACHA);
    const zB = await textNode(BRACHA);
    const zPhB = await anyNode(PH_BRACHOT).catch(() => placeholder(PH_BRACHOT));
    await saveShot('q32-brachot-list.png');
    console.log(`[Q-32] «${BRACHA}» ${zB.w}×${zB.h} (~${linesAtZoom(zB.h, nB.h)} стр.); «${PH_BRACHOT}» ${zPhB.w}×${zPhB.h}`);
    expect(await insideScreenX(zB)).toBe(true);
    expect(notTruncated(zB, nB)).toBe(true);
    expect(linesAtZoom(zB.h, nB.h)).toBeLessThanOrEqual(wordCount(BRACHA));
    expect(await insideScreenX(zPhB)).toBe(true);
    expect(notTruncated(zPhB, nPhB)).toBe(true);

    // 2. Список תהילים — placeholder поиска.
    await openTehilimList();
    const zPhT = await anyNode(PH_TEHILIM).catch(() => placeholder(PH_TEHILIM));
    await saveShot('q32-tehilim-search.png');
    console.log(`[Q-32] «${PH_TEHILIM}» ${zPhT.w}×${zPhT.h}`);
    expect(await insideScreenX(zPhT)).toBe(true);
    expect(notTruncated(zPhT, nPhT)).toBe(true);
    // Глазами по q32-*.png: нет «…» ни в имени брахи, ни в подсказках поиска.
  });
});
